import json, os, time, hashlib
from pathlib import Path
from datetime import datetime, timezone

PID = 1467869
out = {
    "captured_at": datetime.now(timezone.utc).isoformat().replace("+00:00","Z"),
    "note": "pre-cutover snapshot; SHA256 is moment-in-time while writer may still append",
    "pid": PID,
    "alive": Path(f"/proc/{PID}").exists(),
}
if out["alive"]:
    st = Path(f"/proc/{PID}/status").read_text()
    rss = None
    for line in st.splitlines():
        if line.startswith("VmRSS:"):
            rss = int(line.split()[1]) * 1024
        if line.startswith("State:"):
            out["state"] = line.split()[1]
    out["rss_bytes"] = rss
    out["cmdline"] = Path(f"/proc/{PID}/cmdline").read_bytes().replace(b"\0", b" ").decode()
    try:
        out["cpu_etime"] = Path(f"/proc/{PID}/stat").read_text().split()[13:15]
    except Exception:
        pass
    utime, stime = None, None
    parts = Path(f"/proc/{PID}/stat").read_text().split()
    # fields 14,15 are utime stime
    out["utime_ticks"] = int(parts[13])
    out["stime_ticks"] = int(parts[14])

health_path = Path("/home/telgenbuescher/projects/orderbook_analyse/logs/orderbook_v3_raw_archive_btc_doge.health.ndjson")
line = health_path.read_text().strip().splitlines()[-1]
h = json.loads(line)
out["health"] = {
    "collector_state": h.get("collector_state"),
    "rss_mb": h.get("rss_mb"),
    "full_book_enabled": h.get("full_book_enabled"),
    "full_book_active_topics": h.get("full_book_active_topics"),
    "full_ob_flight_recorder_enabled": h.get("full_ob_flight_recorder_enabled"),
    "full_book_runtimes": h.get("full_book_runtimes"),
    "runtimes": h.get("runtimes"),
    "writer_backlog": h.get("writer_backlog"),
    "timing_contract": h.get("timing_contract"),
}

events = {
    "BTCUSDT": Path("/home/telgenbuescher/projects/orderbook_analyse/data/orderbook_raw_shadow/full_ob_edge_flight_recorder/BTCUSDT/2026-09-03/BTCUSDT_20260903T184212Z_4a22a89fe6"),
    "DOGEUSDT": Path("/home/telgenbuescher/projects/orderbook_analyse/data/orderbook_raw_shadow/full_ob_edge_flight_recorder/DOGEUSDT/2026-09-03/DOGEUSDT_20260903T184212Z_f5d68293cd"),
}

def sha256(p):
    h = hashlib.sha256()
    with open(p,'rb') as f:
        for c in iter(lambda: f.read(1<<20), b''):
            h.update(c)
    return h.hexdigest()

def fds_for(path):
    target = str(path.resolve())
    found = []
    fd_dir = Path(f"/proc/{PID}/fd")
    if not fd_dir.exists():
        return found
    for fd in fd_dir.iterdir():
        try:
            link = os.readlink(fd)
        except OSError:
            continue
        if link == target:
            found.append({"fd": fd.name, "link": link})
    return found

out["events"] = {}
for sym, d in events.items():
    rec = {"dir": str(d), "files": {}}
    for name in ["full_ob_raw_deltas.jsonl.zst.tmp","rest_full_snapshot.json.zst.tmp","public_trades_raw.jsonl.zst.tmp"]:
        p = d / name
        if not p.exists():
            continue
        stt = p.stat()
        rec["files"][name] = {
            "path": str(p),
            "size": stt.st_size,
            "mtime": stt.st_mtime,
            "sha256_moment": sha256(p),
            "fds": fds_for(p),
        }
    out["events"][sym] = rec

# other collectors
others = []
for ent in Path("/proc").iterdir():
    if not ent.name.isdigit():
        continue
    try:
        cmd = (ent/"cmdline").read_bytes().replace(b"\0", b" ").decode()
    except Exception:
        continue
    if "orderbook_v2_live" in cmd:
        others.append({"pid": int(ent.name), "cmd": cmd})
out["orderbook_v2_live_processes"] = others

dest = Path("/home/telgenbuescher/projects/spread_recovery_hedge_short_dev/results/btc_doge_full_ob_edge_flight_recorder_v1/edge_capture_1h_v1/PRE_CUTOVER_INVENTORY.json")
