print(json.dumps({k: out[k] for k in ["pid","alive","rss_bytes","health"]}, indent=2)[:2500])
print("events sizes", {s: {n: f["size"] for n,f in rec["files"].items()} for s,rec in out["events"].items()})
print("fds", {s: {n: f["fds"] for n,f in rec["files"].items()} for s,rec in out["events"].items()})
print("collectors", out["orderbook_v2_live_processes"])
print("wrote", dest)
